    <div class="vote_join_detail_box">
      <div class="vote_join_detail_top" @click="return_vote">
        <i class="el-icon-arrow-left"></i>&nbsp;&nbsp;返回【{{vote_info['vote_title']}}】统计
      </div>
      <div class="vote_join_detail_content">
        <div class="vote_title">
          <span class="vote_sort">问题：</span>
          <span class="title_info">{{vote_block.block_title}}</span>
        </div>
        <div class="vote_content">
          <el-container>
          <el-main v-if="join_detail">
            <div  class="table_info">
              <el-table
                :data="join_detail"
                style="width: 100%;text-align: center;">
                <el-table-column
                  prop="join_id"
                  label="ID"
                  min-width="40">
                </el-table-column>
                <el-table-column
