                </el-table-column>
                <el-table-column
                  prop="relative"
                  label="住户身份"
                  min-width="80">
                </el-table-column>
                <el-table-column
                  prop="join_ip"
                  label="最后投票IP"
                  min-width="100">
                </el-table-column>
                <el-table-column
                  v-if="1==vote_block.block_type || 2==vote_block.block_type"
                  prop="vote_option_info"
                  label="填写内容"
                  min-width="120">
                </el-table-column>
                <el-table-column
                  v-if="3==vote_block.block_type || 4==vote_block.block_type"
                  prop="vote_option_info"
                  label="选择内容"
                  min-width="120">
                </el-table-column>
                <el-table-column
                  v-if="5==vote_block.block_type"
                  label="评分"
                  min-width="180">
                  <template slot-scope="scope">
                  <span>
                    <el-rate
                      v-model="scope.row.option_num"
                      disabled
                      show-score
                      text-color="#ff9900"
                      disabled-void-color='#C0C4CC'
                      score-template="{value}">
                    </el-rate>
                  </span>
                  </template>
                </el-table-column>
                <el-table-column
                  prop="vote_time"
                  label="投票时间"
                  min-width="120">
                </el-table-column>
                <el-table-column
                  v-if="limit_type==vote_info.limit_type && from=='house'"
                  label="参与业主有效面积比例"
                  min-width="180">
                  <template slot-scope="scope">
                  <span>
                    {{scope.row.housesize}}㎡/{{house_size_total}}㎡({{scope.row.house_size_proportion}}%)
                  </span>
                  </template>
                </el-table-column>
                <el-table-column
                  v-if="limit_type==vote_info.limit_type && from=='house'"
                  label="所有业主有效面积比例"
                  min-width="180">
                  <template slot-scope="scope">
                  <span>
                    {{scope.row.housesize}}㎡/{{vote_info.owner_house_size_total}}㎡({{scope.row.house_size_proportion_total}}%)
                  </span>
                  </template>
                </el-table-column>
              </el-table>
            </div>
          </el-main>
          <el-footer>
            <div v-show="total_page>0" class="page_msg">
              <el-pagination
                background
                layout="prev, pager, next"
                :page-count="total_page"
                :current-page="page"
                @current-change="current_change"
              >
              </el-pagination>
            </div>
          </el-footer>
          </el-container>
        </div>
      </div>
    </div>
</template>

<script>
  export default {
    name: "vote_join_detail",
    created () {
      this.block_id = this.$route.query.block_id;
      var from = this.$route.query.from;
      if (from) {
        this.from = from;
      }
      if (this.block_id>0) {
        this.statisticalVoteBlockDetail();
      }
    },
    data() {
      return {
        page: 1,
        block_id: '',
        vote_id: '',
        limit_type: 1,
        'option_num_total': 0,
        'house_size_total': 100,
        'count': '1',
        'total_page': 1,
        'vote_info':{
          'vote_id': '8',
          'vote_title': '新装路灯3',
          'vote_des': '小区打算重新安装内部道路的照明3'
        },
        'vote_block':{
          'block_id': '7',
          'vote_id': '8',
          'block_title': '是否安装最新的拟态路灯5',
          'block_type': '3',
          'is_write': '1',
          'block_sort': '1',
          'block_number': '1',
          'block_last_time': '1570773904'
        },
        join_detail: [
          {
            'join_id': '1',
            'vote_id': '8',
              'address':'',
              'relative':'',
            'block_id': '7',
            'option_id': '15',
            'uid': '1358622',
            'bind_id': '364',
            'from': 'house',
            'from_id': '42',
            'option_txt': '1432143214',
            'option_num': '0',
            'add_time': '1571215757',
            'last_time': '1571217322',
            'housesize': '100.00',
            'name': '郭先生',
            'phone': '18556570388',
            'vote_option_info': '【其他】：1432143214',
            'vote_time': '2019-10-16 17:15',
          }
        ],
        from: 'house'
      }
    },
    methods: {
      current_change(val) {
        this.page = val;
        this.statisticalVoteBlockDetail();
        console.log(`当前页: ${val}`);
        console.log(`当前页1: `,this.page);
      },
      // 获取投票区块详情
      async statisticalVoteBlockDetail() {
        let param = {
          page: this.page,
          block_id: this.block_id
        }
        var url_params = '&from=house';
        if (this.from) {
          url_params = '&from=' + this.from;
        }
        let res = await this.$api.statisticalVoteBlockDetail(param, url_params);
        if (res) {
          console.log(`res: `, res);
          if (res.option_num_total) {
            this.option_num_total = res.option_num_total;
          }
          if (res.house_size_total) {
            this.house_size_total = res.house_size_total;
          }
          if (res.count) {
            this.count = res.count;
          }
          if (res.total_page) {
            this.total_page = res.total_page;
          }
          if (res.vote_info) {
            this.vote_info = res.vote_info;
            this.vote_id = this.vote_info.vote_id;
          }
          if (res.vote_block) {
            this.vote_block = res.vote_block;
          }
          if (res.list) {
            this.join_detail = res.list;
          }
        }
      },
      float_num: function(num) {
        return parseFloat(num)
      },
      return_vote: function () {
        this.$router.replace({ path: '/vote_statistics', query: { vote_id: this.vote_id, from: this.from }});
      }
    }
  }
</script>

